jsxGraph.script:
board.suspendUpdate();
board.options.point.withLabel = false;
board.options.point.visible = false;

// Draw standard axes
board.create('arrow', [[-3.5, 0], [4.5, 0]], {strokeColor: '#64748b', strokeWidth: 1.5, fixed: true});
board.create('arrow', [[0, -3.5], [0, 4.5]], {strokeColor: '#64748b', strokeWidth: 1.5, fixed: true});

// Ticks
for (var i = -3; i <= 4; i++) {
  if (i !== 0) {
    board.create('segment', [[i, -0.12], [i, 0.12]], {strokeColor: '#cbd5e1', strokeWidth: 1, fixed: true});
    board.create('segment', [[-0.12, i], [0.12, i]], {strokeColor: '#cbd5e1', strokeWidth: 1, fixed: true});
  }
}

// Line 1: x + y = 3 => y = -x + 3
board.create('functiongraph', [function(x){ return -x + 3; }, -4, 5], {
  strokeColor: '#3b82f6', 
  strokeWidth: 2, 
  fixed: true
});
board.create('text', [-2.2, 4.5, '\(x + y = 3\)'], {
  fontSize: 9.5,
  fontFamily: '"Outfit", "Inter", sans-serif',
  strokeColor: '#3b82f6',
  fixed: true
});

// Line 2: 2x - y = 0 => y = 2x
board.create('functiongraph', [function(x){ return 2*x; }, -4, 5], {
  strokeColor: '#ef4444', 
  strokeWidth: 2, 
  fixed: true
});
board.create('text', [1.5, 3.8, '\(2x - y = 0\)'], {
  fontSize: 9.5,
  fontFamily: '"Outfit", "Inter", sans-serif',
  strokeColor: '#ef4444',
  fixed: true
});

// Intersection Point: (1, 2)
board.create('point', [1, 2], {
  name: 'Intersection (1, 2)',
  color: '#f43f5e',
  strokeColor: '#fda4af',
  strokeWidth: 1.5,
  size: 4.5,
  visible: true,
  withLabel: true,
  fixed: true,
  label: {
    fontSize: 9.5,
    fontFamily: '"Outfit", "Inter", sans-serif',
    strokeColor: '#1e293b',
    offset: [10, 10]
  }
});

board.unsuspendUpdate();

board.suspendUpdate();
board.create('arrow', [[0,0], [0, 48000]], {strokeColor: 'black', strokeWidth: 1});
board.create('arrow', [[0,0], [600, 0]], {strokeColor: 'black', strokeWidth: 1});

board.create('text', [680, -3000, 't (hours)'], {anchorX: 'right', anchorY: 'top', fontSize: 14});
board.create('text', [-40, 52000, 'V (litres)'], {anchorX: 'right', anchorY: 'bottom', fontSize: 14});

board.create('segment', [[-15, 40000], [0, 40000]], {strokeColor: 'black', strokeWidth: 1});
board.create('text', [-20, 40000, '40000'], {anchorX: 'right', anchorY: 'middle', fontSize: 14});

board.create('segment', [[-15, 20000], [0, 20000]], {strokeColor: 'black', strokeWidth: 1});
board.create('text', [-20, 20000, '20000'], {anchorX: 'right', anchorY: 'middle', fontSize: 14});

board.create('segment', [[500, -1500], [500, 0]], {strokeColor: 'black', strokeWidth: 1});
board.create('text', [500, -3000, '500'], {anchorX: 'middle', anchorY: 'top', fontSize: 14});

var p = board.create('point', [500, 20000], {visible: false});
board.create('text', [520, 20000, '(500, 20000)'], {anchorX: 'left', anchorY: 'middle', fontSize: 14, cssClass: 'nowrap-text'});

var pStart = board.create('point', [0, 40000], {visible: false});
board.create('segment', [pStart, p], {strokeColor: 'blue', strokeWidth: 1.5});

board.create('segment', [[500,0], p], {strokeColor: 'red', strokeWidth: 1.5, dash: 2});

board.unsuspendUpdate();

board.suspendUpdate();
board.options.point.withLabel = false;
board.options.point.visible = false;

board.create('arrow', [[-0.2, 0], [2.8, 0]], {strokeColor: '#64748b', strokeWidth: 1.5, fixed: true});
board.create('arrow', [[0, -10], [0, 190]], {strokeColor: '#64748b', strokeWidth: 1.5, fixed: true});

board.create('text', [2.7, 8, 't (h)'], {fontSize: 10, fontFamily: 'sans-serif', strokeColor: '#475569', fixed: true});
board.create('text', [0.1, 185, 'd (km)'], {fontSize: 10, fontFamily: 'sans-serif', strokeColor: '#475569', fixed: true});

for (var t = 0.5; t <= 2.5; t += 0.5) {
  board.create('segment', [[t, -3], [t, 3]], {strokeColor: '#cbd5e1', strokeWidth: 1, fixed: true});
  board.create('text', [t - 0.08, -12, t.toFixed(1)], {fontSize: 8.5, strokeColor: '#64748b', fixed: true});
}
for (var d = 30; d <= 180; d += 30) {
  board.create('segment', [[-0.05, d], [0.05, d]], {strokeColor: '#cbd5e1', strokeWidth: 1, fixed: true});
  board.create('text', [-0.35, d - 3, d], {fontSize: 8.5, strokeColor: '#64748b', fixed: true});
}

board.create('segment', [[0, 30], [2.5, 180]], {strokeColor: '#3b82f6', strokeWidth: 2.5, fixed: true});
board.create('text', [1.8, 130, 'Car A'], {fontSize: 10, strokeColor: '#3b82f6', fixed: true});

board.create('segment', [[0, 120], [1.5, 0]], {strokeColor: '#ef4444', strokeWidth: 2.5, fixed: true});
board.create('text', [0.8, 60, 'Car B'], {fontSize: 10, strokeColor: '#ef4444', fixed: true});

board.unsuspendUpdate();

board.suspendUpdate();
board.options.point.withLabel = false;
board.options.point.visible = false;

board.create('arrow', [[-0.2, 0], [2.8, 0]], {strokeColor: '#64748b', strokeWidth: 1.5, fixed: true});
board.create('arrow', [[0, -10], [0, 190]], {strokeColor: '#64748b', strokeWidth: 1.5, fixed: true});

board.create('text', [2.7, 8, 't (h)'], {fontSize: 10, fontFamily: 'sans-serif', strokeColor: '#475569', fixed: true});
board.create('text', [0.1, 185, 'd (km)'], {fontSize: 10, fontFamily: 'sans-serif', strokeColor: '#475569', fixed: true});

for (var t = 0.5; t <= 2.5; t += 0.5) {
  board.create('segment', [[t, -3], [t, 3]], {strokeColor: '#cbd5e1', strokeWidth: 1, fixed: true});
  board.create('text', [t - 0.08, -12, t.toFixed(1)], {fontSize: 8.5, strokeColor: '#64748b', fixed: true});
}
for (var d = 30; d <= 180; d += 30) {
  board.create('segment', [[-0.05, d], [0.05, d]], {strokeColor: '#cbd5e1', strokeWidth: 1, fixed: true});
  board.create('text', [-0.35, d - 3, d], {fontSize: 8.5, strokeColor: '#64748b', fixed: true});
}

board.create('segment', [[0, 30], [2.5, 180]], {strokeColor: '#3b82f6', strokeWidth: 2.5, fixed: true});
board.create('text', [1.8, 130, 'Car A'], {fontSize: 10, strokeColor: '#3b82f6', fixed: true});

board.create('segment', [[0, 120], [1.5, 0]], {strokeColor: '#ef4444', strokeWidth: 2.5, fixed: true});
board.create('text', [0.8, 60, 'Car B'], {fontSize: 10, strokeColor: '#ef4444', fixed: true});

board.unsuspendUpdate();
